import { ApplicationConfig, provideZoneChangeDetection } from '@angular/core';
import { provideRouter, withComponentInputBinding } from '@angular/router';
import { provideHttpClient } from '@angular/common/http';

import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideRouter(routes, withComponentInputBinding()),
    provideHttpClient(),
  ],
};

import { Component } from '@angular/core';
import { RouterOutlet } from '@angular/router';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet],
  template: `
    <main class="app-shell">
      <router-outlet />
    </main>
  `,
})
export class App {}

export interface CalculationRequest {
  first_number: number;
  second_number: number;
}

export interface CalculationResponse {
  id: string;
  first_number: number;
  second_number: number;
  result: number;
  created_at: string;
}

export interface ProblemDetails {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
}

import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, catchError, map, throwError } from 'rxjs';

import { CalculationRequest, CalculationResponse, ProblemDetails } from '../models/calculation.model';

@Injectable({
  providedIn: 'root',
})
export class CalculationService {
  private readonly http = inject(HttpClient);
  private readonly baseUrl = '/calculations';

  /**
   * POST /calculations — createCalculation
   * Выполняет суммирование двух чисел.
   */
  createCalculation(request: CalculationRequest): Observable<CalculationResponse> {
    return this.http
      .post<CalculationResponse>(this.baseUrl, request)
      .pipe(
        map((response) => response),
        catchError((error: HttpErrorResponse) => {
          const problem: ProblemDetails = error.error ?? {
            title: 'Неизвестная ошибка',
            status: error.status,
          };
          return throwError(() => problem);
        }),
      );
  }
}

import { Component, Input, forwardRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  ControlValueAccessor,
  NG_VALUE_ACCESSOR,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';

@Component({
  selector: 'app-number-input',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, MatFormFieldModule, MatInputModule],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => NumberInputComponent),
      multi: true,
    },
  ],
  template: `
    <mat-form-field appearance="outline" class="number-input-field">
      <mat-label>{{ label }}</mat-label>
      <input
        matInput
        type="number"
        step="any"
        [formControl]="control"
        [placeholder]="placeholder"
        [disabled]="disabled"
      />
      <mat-error *ngIf="control?.hasError('required')">Обязательное поле</mat-error>
      <mat-error *ngIf="control?.hasError('min')">Значение слишком маленькое</mat-error>
      <mat-error *ngIf="control?.hasError('max')">Значение слишком большое</mat-error>
    </mat-form-field>
  `,
})
export class NumberInputComponent implements ControlValueAccessor {
  @Input() label = 'Число';
  @Input() placeholder = 'Введите число';
  @Input() disabled = false;

  private onChange: (value: number | null) => void = () => {};
  private onTouched: () => void = () => {};

  control = new (import('@angular/forms').FormControl)(null, {
    validators: [Validators.required, Validators.min(-1e15), Validators.max(1e15)],
    updateOn: 'change',
  });

  writeValue(value: number | null): void {
    this.control.setValue(value ?? null, { emitEvent: false });
  }

  registerOnChange(fn: (value: number | null) => void): void {
    this.onChange = fn;
    this.control.valueChanges.subscribe((value) => this.onChange(value));
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    if (isDisabled) {
      this.control.disable({ emitEvent: false });
    } else {
      this.control.enable({ emitEvent: false });
    }
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
