import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';

import { CalculationService } from '../../services/calculation.service';
import { CalculationResponse, ProblemDetails } from '../../models/calculation.model';
import { NumberInputComponent } from '../../components/number-input/number-input.component';
import { SubmitButtonComponent } from '../../components/submit-button/submit-button.component';
import { ErrorMessageComponent } from '../../components/error-message/error-message.component';
import { LoadingIndicatorComponent } from '../../components/loading-indicator/loading-indicator.component';

type ScreenState = 'empty' | 'loading' | 'error' | 'success';

@Component({
  selector: 'app-calculation-form',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatCardModule,
    MatButtonModule,
    MatIconModule,
    NumberInputComponent,
    SubmitButtonComponent,
    ErrorMessageComponent,
    LoadingIndicatorComponent,
  ],
  template: `
    <div class="calculation-form">
      <mat-card class="calculation-form__card">
        <mat-card-header>
          <mat-icon mat-card-avatar>add</mat-icon>
          <mat-card-title>Форма ввода чисел</mat-card-title>
          <mat-card-subtitle>Введите два числа для вычисления суммы</mat-card-subtitle>
        </mat-card-header>

        <mat-card-content>
          <!-- Состояние: loading -->
          <app-loading-indicator
            *ngIf="state === 'loading'"
            label="Выполняется вычисление…"
          />

          <!-- Состояние: error -->
          <app-error-message
            *ngIf="state === 'error'"
            [message]="errorMessage"
            title="Ошибка вычисления"
          />

          <!-- Состояния: empty / success -->
          <form
            *ngIf="state === 'empty' || state === 'success'"
            [formGroup]="form"
            (ngSubmit)="onSubmit()"
            class="calculation-form__form"
          >
            <app-number-input
              formControlName="firstNumber"
              label="Первое число"
              placeholder="Например: 42"
            />
            <app-number-input
              formControlName="secondNumber"
              label="Второе число"
              placeholder="Например: 17"
            />

            <div class="calculation-form__actions">
              <app-submit-button
                label="Вычислить сумму"
                [loading]="state === 'loading'"
                [disabled]="form.invalid"
              />
              <button
                mat-stroked-button
                color="basic"
                type="button"
                (click)="onClear()"
              >
                Очистить форму
              </button>
            </div>
          </form>
        </mat-card-content>
      </mat-card>
    </div>
  `,
})
export class CalculationFormComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly router = inject(Router);
  private readonly calculationService = inject(CalculationService);

  state: ScreenState = 'empty';
  errorMessage = '';

  form = this.fb.nonNullable.group({
    firstNumber: [0, [Validators.required, Validators.min(-1e15), Validators.max(1e15)]],
    secondNumber: [0, [Validators.required, Validators.min(-1e15), Validators.max(1e15)]],
  });

  ngOnInit(): void {
    this.form.valueChanges.subscribe(() => {
      if (this.state === 'error' && this.form.valid) {
        this.state = 'success';
        this.errorMessage = '';
      }
    });
  }

  onSubmit(): void {
    if (this.form.invalid) {
      this.state = 'error';
      this.errorMessage = 'Пожалуйста, заполните все поля корректными числами.';
      return;
    }

    this.state = 'loading';
    this.errorMessage = '';

    const payload = {
      first_number: this.form.value.firstNumber,
      second_number: this.form.value.secondNumber,
    };

    this.calculationService.createCalculation(payload).subscribe({
      next: (response: CalculationResponse) => {
        this.state = 'success';
        this.router.navigate(['/result'], {
          state: { calculation: response },
        });
      },
      error: (problem: ProblemDetails) => {
        this.state = 'error';
        this.errorMessage =
          problem.detail || problem.title || 'Не удалось выполнить вычисление. Попробуйте ещё раз.';
      },
    });
  }

  onClear(): void {
    this.form.reset({ firstNumber: 0, secondNumber: 0 });
    this.state = 'empty';
    this.errorMessage = '';
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';

import { CalculationResponse, ProblemDetails } from '../../models/calculation.model';
import { CalculationService } from '../../services/calculation.service';
import { ResultDisplayComponent } from '../../components/result-display/result-display.component';
import { ErrorMessageComponent } from '../../components/error-message/error-message.component';
import { LoadingIndicatorComponent } from '../../components/loading-indicator/loading-indicator.component';

type ScreenState = 'empty' | 'loading' | 'error' | 'success';

@Component({
  selector: 'app-calculation-result',
  standalone: true,
  imports: [
    CommonModule,
    MatCardModule,
    MatButtonModule,
    MatIconModule,
    ResultDisplayComponent,
    ErrorMessageComponent,
    LoadingIndicatorComponent,
  ],
  template: `
    <div class="calculation-result">
      <mat-card class="calculation-result__card">
        <mat-card-header>
          <mat-icon mat-card-avatar>sum</mat-icon>
          <mat-card-title>Результат суммирования</mat-card-title>
        </mat-card-header>

        <mat-card-content>
          <!-- Состояние: empty -->
          <div *ngIf="state === 'empty'" class="calculation-result__empty">
            <mat-icon class="calculation-result__empty-icon">hourglass_empty</mat-icon>
            <p>Результат ещё не вычислен.</p>
            <p>Вернитесь к форме и выполните вычисление.</p>
          </div>

          <!-- Состояние: loading -->
          <app-loading-indicator
            *ngIf="state === 'loading'"
            label="Ожидание ответа сервера…"
          />

          <!-- Состояние: error -->
          <app-error-message
            *ngIf="state === 'error'"
            [message]="errorMessage"
            title="Ошибка вычисления"
          />

          <!-- Состояние: success -->
          <app-result-display
            *ngIf="state === 'success' && calculation"
            [result]="calculation.result"
            [firstNumber]="calculation.first_number"
            [secondNumber]="calculation.second_number"
            [createdAt]="calculation.created_at"
          />
        </mat-card-content>

        <mat-card-actions class="calculation-result__actions">
          <button mat-flat-button color="primary" (click)="onNewCalculation()">
            <mat-icon>refresh</mat-icon>
            Новое вычисление
          </button>
        </mat-card-actions>
      </mat-card>
    </div>
  `,
})
export class CalculationResultComponent implements OnInit {
  private readonly router = inject(Router);
  private readonly calculationService = inject(CalculationService);

  state: ScreenState = 'empty';
  errorMessage = '';
  calculation: CalculationResponse | null = null;

  ngOnInit(): void {
    const navigationState = this.router.getCurrentNavigation()?.extras.state as
      | { calculation?: CalculationResponse }
      | undefined;

    if (navigationState?.calculation) {
      this.calculation = navigationState.calculation;
      this.state = 'success';
      return;
    }

    // Если пользователь открыл страницу напрямую — показываем empty
    this.state = 'empty';
  }

  onNewCalculation(): void {
    this.router.navigate(['/form']);
  }
}

@use '@angular/material' as mat;

@include mat.core();

$theme: mat.define-light-theme((
  color: (
    primary: mat.define-palette(mat.$indigo-palette),
    accent: mat.define-palette(mat.$pink-palette, A200, A100, A400),
    warn: mat.define-palette(mat.$red-palette),
  ),
  typography: mat.define-typography-config(),
));

@include mat.all-component-themes($theme);

html, body {
  height: 100%;
  margin: 0;
  font-family: Roboto, 'Helvetica Neue', sans-serif;
}

.app-shell {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: #f5f5f5;
}

/* Calculation Form */
.calculation-form {
  width: 100%;
  max-width: 480px;

  &__card {
    width: 100%;
  }

  &__form {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  &__actions {
    display: flex;
    gap: 12px;
    margin-top: 16px;
    flex-wrap: wrap;
  }
}

/* Calculation Result */
.calculation-result {
  width: 100%;
  max-width: 480px;

  &__card {
    width: 100%;
  }

  &__empty {
    text-align: center;
    padding: 24px 0;
    color: #757575;

    &-icon {
      font-size: 48px;
      width: 48px;
      height: 48px;
      margin-bottom: 8px;
    }
  }

  &__actions {
    justify-content: center;
    padding: 16px;
  }
}

/* Components */
.number-input-field {
  width: 100%;
}

.submit-button__loading {
  opacity: 0.7;
}

.error-message {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  margin: 16px 0;
  background: #ffebee;
  border: 1px solid #ef9a9a;
  border-radius: 8px;

  &__icon {
    color: #d32f2f;
  }

  &__title {
    margin: 0 0 4px;
    font-weight: 500;
    color: #c62828;
  }

  &__text {
    margin: 0;
    color: #b71c1c;
  }
}

.result-display {
  margin-top: 16px;

  &__icon {
    color: #388e3c;
  }

  &__formula {
    font-size: 18px;
    color: #616161;
    margin: 0 0 8px;
  }

  &__value {
    font-size: 32px;
    font-weight: 700;
    color: #2e7d32;
    margin: 0 0 8px;
  }

  &__meta {
    font-size: 13px;
    color: #9e9e9e;
    margin: 0;
  }
}

.loading-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 32px 0;

  &__label {
    margin: 0;
    color: #757575;
  }
}

import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from './app/app.component';
import { appConfig } from './app/app.config';

